import {mergeEdupageData} from './edupage.js';
import {COLORS,estimatedGrade,gradeSummary,weightedAverage,mondayOf,scheduleForDate,lessonsOverlap,lessonStatus,uid,todayKey,addDays,localKey,dayDifference,dueLabel,safeUrl,validDate,initialState,validateState,demoState} from './core.js';
import {mergeSchoolSnapshot,calendarText,SCHOOL_CHECKED_AT} from './school.js';
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 9 1 1 2-2m2 1h3M8 15l1 1 2-2m2 1h3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-12 4h.01M12 15h.01M16 15h.01"/>',book:'<path d="M12 6c-3-3-7-3-10-2v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-1-10 2Zm0 0v15"/>',focus:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',settings:'<path d="m10 3-1 3-3 1-3-1-1 3 2 3-1 3 2 3h3l2 3 3-1 2-2 3-1 1-3-2-2V9l1-3-3-1-2 1-3-3z"/><circle cx="12" cy="12" r="3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a3 3 0 0 0-4-4L5 15z"/>',link:'<path d="m10 14 4-4m-6 2-3 3a4 4 0 0 0 6 6l3-3m-4-12 3-3a4 4 0 0 1 6 6l-3 3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.book}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s), content=$('#content'),modal=$('#modal');
const KEY='orbit.school.v1'; const nativeMode=!!globalThis.orbitNative;let storageAvailable=true,storageReadError=false;
let state=initialState();try {if(nativeMode&&globalThis.orbitInitialReadError)throw Error('Read failed');const raw=nativeMode?globalThis.orbitInitialState:localStorage.getItem(KEY); if(raw)state=validateState(typeof raw==='string'?JSON.parse(raw):raw); } catch {storageAvailable=false;storageReadError=true;}
mergeSchoolSnapshot(state);attachNotionPages();
let ownState=state,isDemo=false,view='home',filter='open',query='',subjectFilter='',selectedDate=todayKey(),calendarDate=new Date(selectedDate+'T12:00:00'),weekDay=weekday();
let syncBusy=false,syncErrorText='',lastRenderedDate=todayKey();let extensionMode=false,kindFilter='',scheduleWeek=mondayOf(todayKey()),clockSignature='';if(new Date(todayKey()+'T12:00:00Z').getUTCDay()===0)scheduleWeek=addDays(scheduleWeek,7);
let timer=state.focusTimer?{...state.focusTimer}:{minutes:25,remaining:25*60,running:false,endsAt:0},toastTimeout;let ownTimer={...timer};
const weekdays=['','Pondělí','Úterý','Středa','Čtvrtek','Pátek'];
const kinds={task:'Úkol',test:'Test',project:'Projekt'};
const navItems=[['home','Přehled','home'],['tasks','Úkoly a testy','tasks'],['schedule','Celý rozvrh','calendar'],['grades','Známky','star'],['subjects','Předměty','book'],['notion','Zápisky v Notionu','book'],['focus','Soustředění','focus']];
function weekday(){const d=new Date(todayKey()+'T12:00:00').getDay();return d>0&&d<6?d:1;}
function subject(id){return state.subjects.find(s=>s.id===id);}
function nativeSend(type,payload={}){globalThis.webkit?.messageHandlers?.orbit?.postMessage({type,...payload});}
function persist(){if(isDemo||storageReadError)return false;state.clientVersion='4.3';state.focusTimer={...timer};try{if(nativeMode)nativeSend('save',{json:JSON.stringify(state)});else localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;toast('Data se nepodařilo uložit. Stáhni si zálohu v Nastavení.');}updateSaveStatus();return storageAvailable;}

function updateSaveStatus(){const el=$('#save-status');el.innerHTML=isDemo?'Ukázková data · neukládají se':storageAvailable?(nativeMode?'Ukládáno na tomto Macu <i></i>':'Ukládáno v tomto prohlížeči <i></i>'):'Uložení není dostupné · stáhni zálohu';}
function toast(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});}
function schoolUrl(type){const email=encodeURIComponent(state.profile.email);return type==='classroom'?`https://classroom.google.com/?authuser=${email}`:type==='drive'?`https://drive.google.com/drive/u/?authuser=${email}`:type==='gmail'?`https://mail.google.com/mail/?authuser=${email}`:safeUrl(state.profile.edupage);}
function render(){
 lastRenderedDate=todayKey();
 $('#nav').innerHTML=navItems.map(([v,label,i])=>`<button class="nav-item ${view===v?'active':''}" data-action="navigate" data-view="${v}" ${view===v?'aria-current="page"':''} title="${label}">${icon(i)}<span>${label}</span>${v==='tasks'&&state.tasks.filter(t=>!t.done).length?`<span class="nav-count">${state.tasks.filter(t=>!t.done).length}</span>`:''}</button>`).join('');
 $('#profileName').textContent=state.profile.name;$('#breadcrumb').textContent=navItems.find(n=>n[0]===view)?.[1]||'Nastavení';
 const banner=isDemo?'<div class="demo-banner"><span>Ukázkový režim · tyto úkoly ani rozvrh nejsou ze školy.</span><button data-action="demo-exit">Zpět k mým datům</button></div>':'';
 content.innerHTML=banner+'<div id="sync-status" class="sync-status" role="status" hidden></div>'+({home:homeView,tasks:tasksView,schedule:scheduleView,grades:gradesView,subjects:subjectsView,settings:settingsView,notion:notionView,focus:focusView}[view]||homeView)();
 hydrateIcons();updateSaveStatus();updateTimer();updateLessonClock();updateSyncStatus();
}
function heading(title,sub='',button=true){return `<div class="page-heading"><div><div class="eyebrow">${icon('sun')} TVŮJ ŠKOLNÍ PROSTOR</div><h1>${title}</h1>${sub?`<p class="heading-sub">${sub}</p>`:''}</div><div class="heading-actions"><span class="date-label">${icon('calendar')}${new Date(todayKey()+'T12:00:00').toLocaleDateString('cs-CZ',{day:'numeric',month:'long',year:'numeric'})}</span>${button?`<button class="primary-button" data-action="task-new">${icon('plus')} Přidat úkol</button>`:''}</div></div>`;}
function panelHeading(title,sub='',action='',label='Zobrazit vše'){return `<div class="panel-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action?`<button class="small-link" data-action="${action}">${label} ${icon('arrow')}</button>`:''}</div>`;}
function empty(title,description,action='',label='Přidat úkol',i='tasks'){return `<div class="empty-state"><div class="empty-icon">${icon(i)}</div><h3>${title}</h3><p>${description}</p>${action?`<button class="secondary-button" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function matchesFilter(t){const delta=dayDifference(t.due,todayKey());return filter==='done'?t.done:filter==='all'?true:!t.done&&(filter==='priority'?t.priority:filter==='today'?delta===0:filter==='week'?delta>=0&&delta<=7:filter==='overdue'?delta<0:true);}
function sortedTasks(){return [...state.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||a.due.localeCompare(b.due)||Number(b.priority)-Number(a.priority));}
function taskRow(t){const s=subject(t.subject),diff=dayDifference(t.due,todayKey());return `<div class="task-row ${t.done?'done':''}" style="--subject-color:${s?.color||'#8b9fff'}"><button class="check" data-action="task-toggle" data-id="${esc(t.id)}" aria-label="${t.done?'Vrátit mezi nesplněné':'Označit jako hotové'}: ${esc(t.title)}" aria-pressed="${t.done}">${t.done?icon('check'):''}</button><button class="task-main" data-action="task-edit" data-id="${esc(t.id)}"><span class="task-name">${esc(t.title)}</span><span class="task-meta"><span class="subject-dot"></span>${esc(s?.name||'Osobní')}<span>·</span>${kinds[t.kind]}<span>·</span>${esc(t.source||'Vlastní')}${t.statusUnverified&&!t.done?'<span class="unverified">ověřit odevzdání</span>':''}</span></button><span class="due-pill ${diff<0&&!t.done?'overdue':diff>1||t.done?'later':''}">${dueLabel(t.due)}${t.dueTime?` · ${esc(t.dueTime)}`:''}</span><button class="star-button ${t.priority?'selected':''}" data-action="task-star" data-id="${esc(t.id)}" aria-label="${t.priority?'Odebrat prioritu':'Přidat prioritu'}" aria-pressed="${t.priority}">${icon('star')}</button></div>`;}
function overviewWeek(){const dates=Array.from({length:5},(_,i)=>addDays(scheduleWeek,i)),known=dates.filter(d=>state.scheduleDays?.[d]?.status==='complete').length;
 return `<section class="panel overview-week"><div class="panel-heading"><div><span class="subject-kicker">ROZVRH · ${shortDate(scheduleWeek)} — ${shortDate(addDays(scheduleWeek,4))}</span><h2>Celý týden na jednom místě</h2></div><div class="overview-actions"><span class="connection-pill ${known===5?'connected':''}">${known}/5 dní načteno</span><button class="small-link" data-action="all-schedule">Detail rozvrhu ${icon('arrow')}</button></div></div><div class="overview-days">${dates.map((date,i)=>{const rows=scheduleForDate(state.lessons,date,state.substitutions,state.events),active=rows.filter(l=>!l.cancelled),knownDay=state.scheduleDays?.[date]?.status==='complete',event=(state.events||[]).find(e=>e.date===date);return `<button class="overview-day ${date===todayKey()?'today':''}" data-action="overview-day" data-day="${i+1}" data-date="${date}" data-lesson-count="${rows.length}"><span class="overview-day-head"><strong>${weekdays[i+1]}</strong><span>${shortDate(date)}</span></span><span class="overview-day-count">${active.length?active.length+' hodin':event?'Volno':knownDay?'Bez výuky':'Nenačteno'}</span><span class="overview-mini-lessons">${rows.slice(0,3).map(l=>`<span class="overview-mini-lesson ${l.cancelled?'cancelled':''}" style="--subject-color:${subject(l.subject)?.color||'#8c9dff'}"><time>${esc(l.start)}</time><b>${esc(subject(l.subject)?.name||'Hodina')}</b></span>`).join('')}${event?`<span class="overview-holiday">${esc(event.title)}</span>`:''}${!rows.length&&!event&&!knownDay?'<span class="overview-missing">Klikni na Synchronizovat EduPage</span>':''}</span><span class="overview-day-footer">${active.length?'Konec '+esc(active.at(-1).end):'Detail dne'}<span>↗</span></span></button>`;}).join('')}</div></section>`;
}
function homeView(){const open=state.tasks.filter(t=>!t.done),today=open.filter(t=>t.due===todayKey()),tests=open.filter(t=>t.kind==='test'&&dayDifference(t.due,todayKey())>=0),next=sortedTasks().find(t=>!t.done),list=sortedTasks().filter(matchesFilter).slice(0,6),completed=state.tasks.filter(t=>t.done).length;
 return heading('Přehled',new Date(todayKey()+'T12:00:00').toLocaleDateString('cs-CZ',{weekday:'long',day:'numeric',month:'long'}))+`<div class="home-top"><section class="panel agenda-hero"><div class="agenda-top"><span class="live-label"><i></i>${next&&dayDifference(next.due,todayKey())<0?'PO TERMÍNU':'NEJBLIŽŠÍ TERMÍN'}</span><span class="source-chip">${esc(next?.source||'Orbit')}</span></div><div class="agenda-content"><div><h2 title="${esc(next?.title||'')}">${next?esc(next.title):'Žádné otevřené úkoly'}</h2><p>${next?esc(subject(next.subject)?.name||'Osobní')+' · '+kinds[next.kind]:'Přidej úkol, test nebo projekt.'}</p><div class="agenda-actions"><button class="hero-button" data-action="${next?'task-edit':'task-new'}" ${next?'data-id="'+esc(next.id)+'"':''}>${next?'Otevřít úkol':'Přidat úkol'} ${icon('arrow')}</button>${next?.sourceUrl?`<a class="hero-link" href="${esc(safeUrl(next.sourceUrl))}" target="_blank" rel="noopener noreferrer">Zadání ↗</a>`:''}</div></div><div class="deadline-date"><span class="date-card-holes"><i></i><i></i></span><small>${next?dueLabel(next.due):'Orbit'}</small><span>${next?new Date(next.due+'T12:00:00').getDate():'✓'}</span><strong>${next?new Date(next.due+'T12:00:00').toLocaleDateString('cs-CZ',{month:'long'}):'Hotovo'}</strong><em>${next?.dueTime?esc(next.dueTime):'Čas neuveden'}</em></div></div></section><div class="home-metrics">${[['today','Dnes odevzdat',today.length,'clock'],['open','K dokončení',open.length,'tasks'],['tests','Nadcházející testy',tests.length,'book']].map(([f,title,n,i])=>`<button class="panel metric metric-${f}" data-action="${f==='tests'?'tests':'quick-filter'}" data-filter="${f}"><span class="metric-icon">${icon(i)}</span><span class="metric-copy"><small>${title}</small><strong>${String(n).padStart(2,'0')}</strong></span><span class="metric-arrow">↗</span></button>`).join('')}</div></div><div class="lesson-live panel" id="lesson-live" aria-live="off"></div>${overviewWeek()}<div class="home-bottom"><div class="home-main"><section class="panel task-panel">${panelHeading('Úkoly a testy <span class="count-pill">'+open.length+'</span>','','all-tasks')}<div class="tabs">${[['open','Otevřené'],['today','Dnes'],['priority','Priority'],['done','Hotovo · '+completed]].map(([f,title])=>`<button class="tab ${filter===f?'active':''}" data-action="home-filter" data-filter="${f}">${title}</button>`).join('')}</div>${list.length?list.map(taskRow).join(''):empty('V tomto filtru je volno.','Změň filtr nebo přidej úkol.','task-new')}<p class="local-only-note">Dokončení v Orbitu nemění odevzdání ve škole.</p></section><div class="sources-row"><a class="panel source" href="${esc(schoolUrl('classroom'))}" target="_blank" rel="noopener noreferrer"><span class="source-logo">${icon('book')}</span><div><strong>Classroom</strong><small>Zadání a materiály ↗</small></div></a><button class="panel source" data-action="navigate" data-view="grades"><span class="source-logo">A</span><div><strong>Známky</strong><small>Hodnocení a průměry ↗</small></div></button><button class="panel source" data-action="navigate" data-view="notion"><span class="source-logo">N</span><div><strong>Notion</strong><small>Tvoje zápisky ↗</small></div></button></div><section class="panel quick-note"><div class="panel-heading"><h2>Rychlá poznámka</h2><span class="note-save-state" id="quick-note-status">Automaticky se ukládá</span></div><textarea id="quick-note" maxlength="20000" placeholder="Nápad, poznámka z hodiny, něco na později…">${esc(state.quickNote||'')}</textarea></section></div><aside class="home-side">${focusCard()}<section class="panel calendar">${calendar()}</section><button class="source-status" data-action="sources"><span class="tiny-dot"></span><span>Poslední školní data · ${formatChecked(state.schoolCheckedAt||SCHOOL_CHECKED_AT)}<small>Stav propojení a načtených částí</small></span>${icon('chevron')}</button></aside></div>`;
}

function formatChecked(value){if(!value||!Number.isFinite(Date.parse(value)))return 'neověřeno';return new Date(value).toLocaleString('cs-CZ',{timeZone:'Europe/Prague',day:'numeric',month:'numeric',hour:'2-digit',minute:'2-digit'});}
function nextSchoolDate(){const today=todayKey(),now=new Date();for(let i=0;i<14;i++){const key=addDays(today,i),n=new Date(key+'T12:00:00Z').getUTCDay(),ls=scheduleForDate(state.lessons,key,state.substitutions,state.events).filter(l=>!l.cancelled);if(n<1||n>5||(state.events||[]).some(e=>e.date===key&&(e.holiday||/ředitelské volno|den boje za svobodu/i.test(e.title))))continue;if(i===0&&ls.length&&lessonStatus(state.lessons,now,state.substitutions,state.events).phase==='finished')continue;return{key,day:n,label:new Date(key+'T12:00:00').toLocaleDateString('cs-CZ',{weekday:'long',day:'numeric',month:'numeric'})};}return{key:today,day:1,label:'Rozvrh'};}

function weekStrip(){return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const key=addDays(todayKey(),i),ts=state.tasks.filter(t=>t.due===key&&!t.done),event=(state.events||[]).find(e=>e.date===key);return `<button class="week-day ${i===0?'current':''} ${ts.length?'busy':''}" data-action="calendar-date" data-date="${key}"><span>${new Date(key+'T12:00:00').toLocaleDateString('cs-CZ',{weekday:'short'})}</span><strong>${new Date(key+'T12:00:00').getDate()}</strong><small>${ts.length?ts.length+' '+(ts.length===1?'termín':'termíny'):event?'Volno':'—'}</small><i class="${ts.some(t=>t.kind==='test')?'test':''}"></i></button>`;}).join('')}</div>`;}
function sourcesModal(){const statusNames={read:'Data načtena',partial:'Částečně načteno',account_unverified:'Ověř správný účet',no_recognized_deadlines:'Na stránce nebyly rozpoznány termíny'};showModal(modalHeader('Školní zdroje')+`<p class="modal-description">${extensionMode?'Rozšíření čte rozpoznané termíny ze školních stránek otevřených v Chrome. Neotevírá žádné účty samo a nic ve škole neodesílá.':'Orbit obsahuje uložený přehled. Přihlášení z Chrome se do samostatné aplikace nepřenáší. EduPage můžeš otevřít přímo v okně Orbitu.'}</p>${['Classroom','EduPage'].map(source=>{const live=state.liveSources?.[source];return `<div class="status-line"><strong>${source}</strong><span class="status">${live?esc(statusNames[live.status]||'Stránka zkontrolována'):'Jednorázový přehled'}</span></div><p class="storage-note">Poslední kontrola: ${formatChecked(live?.checkedAt||SCHOOL_CHECKED_AT)}. Přehled může být neúplný. ${source==='Classroom'?'Ověř svůj školní účet. Otevři přehled K odevzdání a vybraný kurz.':(state.eduSync?.checkedAt?'Osobní rozvrh a číselné známky načteny konektorem. Podrobný seznam školního suplování není samostatně ověřen.':'Ve veřejné šabloně nejsou žádné skutečné školní hodiny. Celý rozvrh načteš tlačítkem Synchronizovat EduPage.')}</p><a class="secondary-button" href="${esc(schoolUrl(source==='Classroom'?'classroom':'edupage'))}" target="_blank" rel="noopener noreferrer">Otevřít ${source} ↗</a>`;}).join('')}<p class="settings-description">${extensionMode?'Aktualizace proběhne jen u otevřených stránek. Nerozpoznané nebo chybějící zadání není považováno za hotové. Odevzdání ověřuj vždy v původní službě.':'Přihlášení v prohlížeči je oddělené od aplikace. Přihlášení ve vedlejší aplikaci se samostatným HTML automaticky nesdílí.'}</p>`);}

function calendar(){const year=calendarDate.getFullYear(),month=calendarDate.getMonth(),first=new Date(year,month,1),offset=(first.getDay()+6)%7,start=new Date(year,month,1-offset);return `<div class="calendar-header"><h2>${calendarDate.toLocaleDateString('cs-CZ',{month:'long',year:'numeric'})}</h2><div class="calendar-arrows"><button class="icon-button" data-action="month-prev" aria-label="Předchozí měsíc">${icon('left')}</button><button class="icon-button" data-action="month-next" aria-label="Další měsíc">${icon('chevron')}</button></div></div><div class="calendar-grid">${['Po','Út','St','Čt','Pá','So','Ne'].map(d=>`<span class="calendar-day-name">${d}</span>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=localKey(d);return `<button class="calendar-day ${d.getMonth()!==month?'outside':''} ${key===todayKey()?'today':''} ${key===selectedDate?'selected':''} ${state.tasks.some(t=>t.due===key&&!t.done)?'has-tasks':''}" data-action="calendar-date" data-date="${key}" aria-label="${d.toLocaleDateString('cs-CZ')}${state.tasks.some(t=>t.due===key&&!t.done)?', obsahuje úkoly':''}" ${key===todayKey()?'aria-current="date"':''}>${d.getDate()}</button>`;}).join('')}</div><div class="calendar-bottom"><span></span>Tečka označuje uložené termíny</div>`;}
function lessonPreview(){const next=nextSchoolDate();const ls=scheduleForDate(state.lessons,next.key,state.substitutions,state.events).filter(l=>!l.cancelled);return ls.length?ls.slice(0,4).map(l=>`<div class="lesson" style="--subject-color:${subject(l.subject)?.color}"><div class="lesson-time">${esc(l.start)}</div><div class="lesson-body"><strong>${esc(subject(l.subject)?.name)}</strong><small>${esc(l.room||l.source||'Vlastní rozvrh')} · do ${esc(l.end)}</small></div></div>`).join('')+`<p class="storage-note">${ls.length} hodin · konec ${esc(ls.at(-1).end)}</p>`:empty('Rozvrh pro tento den nemáš uložený.','Aktuální výuku ověř v EduPage.','lesson-new','Přidat hodinu','calendar');}
function focusCard(){return `<section class="panel focus-card"><div class="panel-heading"><h2>Časovač soustředění</h2><span style="color:#a39ae9">${icon('focus')}</span></div><div class="focus-label">25, 45 nebo 60 minut</div><div class="focus-clock" data-clock>25:00</div><div class="focus-sub" data-timer-label>Soustředěný blok</div><div class="focus-controls"><button class="primary-button" data-action="timer-toggle" data-timer-button>${icon('play')} Začít</button><button class="icon-button" data-action="timer-reset" aria-label="Vynulovat časovač">${icon('reset')}</button></div><div class="focus-presets">${[25,45,60].map(n=>`<button class="${timer.minutes===n?'active':''}" data-action="timer-preset" data-minutes="${n}">${n} min</button>`).join('')}</div><div class="progress-line"><span data-timer-progress></span></div></section>`;}
function tasksView(){let ts=sortedTasks().filter(t=>matchesFilter(t)&&(!kindFilter||t.kind===kindFilter)&&(!subjectFilter||t.subject===subjectFilter)&&(!query||t.title.toLocaleLowerCase('cs').includes(query.toLocaleLowerCase('cs'))));return heading('Úkoly a testy','Termíny ze školy a vlastní úkoly.')+`<section class="panel full-panel"><div class="toolbar"><input class="input" id="task-search" type="search" value="${esc(query)}" placeholder="Najít úkol…" aria-label="Najít úkol"><select id="task-filter" aria-label="Stav úkolu">${[['open','K dokončení'],['today','Dnes'],['week','Do 7 dnů'],['overdue','Po termínu'],['priority','Priority'],['done','Hotovo'],['all','Všechny úkoly']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><select id="kind-filter" aria-label="Typ úkolu"><option value="">Všechny typy</option>${Object.entries(kinds).map(([v,l])=>`<option value="${v}" ${kindFilter===v?'selected':''}>${l}</option>`).join('')}</select><select id="subject-filter" aria-label="Předmět"><option value="">Všechny předměty</option>${state.subjects.map(s=>`<option value="${esc(s.id)}" ${subjectFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div id="task-list">${ts.length?ts.map(taskRow).join(''):empty('Tady je zatím volno.','Zkus jiný filtr nebo si přidej další úkol.','task-new')}</div></section>`;}
function scheduleView(){const date=addDays(scheduleWeek,weekDay-1),lessons=scheduleForDate(state.lessons,date,state.substitutions,state.events),changes=(state.substitutions||[]).filter(s=>s.date>=scheduleWeek&&s.date<=addDays(scheduleWeek,4)),published=(state.providerChanges||[]).filter(c=>c.date>=scheduleWeek&&c.date<=addDays(scheduleWeek,4));
 return heading('Rozvrh',`Celý týden · ${shortDate(scheduleWeek)} – ${shortDate(addDays(scheduleWeek,4))}`,false)+`<section class="panel weekly-panel"><div class="panel-heading"><div class="schedule-controls"><button class="icon-button" data-action="week-prev" aria-label="Předchozí týden">${icon('left')}</button><button class="secondary-button" data-action="week-today">Tento týden</button><button class="icon-button" data-action="week-next" aria-label="Další týden">${icon('chevron')}</button></div><div class="schedule-controls"><button class="secondary-button" data-action="edupage-sync">Synchronizovat</button><button class="secondary-button" data-action="school-timetable">EduPage ↗</button><button class="primary-button" data-action="lesson-new">${icon('plus')} Hodina</button></div></div><div class="weekly-scroll"><div class="weekly-grid">${weekdays.slice(1).map((name,i)=>{const key=addDays(scheduleWeek,i),rows=scheduleForDate(state.lessons,key,state.substitutions,state.events),event=(state.events||[]).find(e=>e.date===key),known=state.scheduleDays?.[key]?.status==='complete';return `<div class="week-column ${key===todayKey()?'is-today':''} ${weekDay===i+1?'is-selected':''}"><button class="week-column-heading" data-action="weekday" data-day="${i+1}"><span>${name}</span><strong>${shortDate(key)}</strong>${key===todayKey()?'<i>Dnes</i>':''}</button><div class="week-column-body">${event?`<div class="school-event">${esc(event.title)}</div>`:''}${rows.map(l=>`<button class="week-lesson ${l.cancelled?'cancelled':''} ${l.change?'has-change':''}" style="--subject-color:${subject(l.subject)?.color||'#8c9dff'}" data-action="lesson-detail" data-id="${esc(l.id)}" data-date="${key}"><span class="week-lesson-time">${esc(l.start)}–${esc(l.end)}</span><strong>${esc(subject(l.subject)?.name||'Hodina')}</strong><small>${l.cancelled?'Odpadá':l.change?'Změna · '+esc(l.room||l.teacher||'suplování'):esc(l.room||'')}</small></button>`).join('')}${!rows.length&&!event?`<div class="day-unknown">${icon('calendar')}<span>${known?'Bez výuky':'Zatím nenačteno'}</span>${!known?'<small>Ověřit v EduPage</small>':''}</div>`:''}</div></div>`;}).join('')}</div></div><div class="schedule-legend"><span><i></i> Uložená hodina</span><span><i class="changed"></i> Změna / suplování</span><span><i class="cancelled"></i> Odpadá</span></div></section>
 <div class="schedule-bottom"><section class="panel"><div class="panel-heading"><h2>${weekdays[weekDay]} · ${shortDate(date)}</h2><button class="small-link" data-action="change-new">Zapsat změnu ${icon('plus')}</button></div>${lessons.length?lessons.map(l=>`<div class="timetable-row ${l.cancelled?'cancelled':''}" style="--subject-color:${subject(l.subject)?.color}"><div class="time-block">${esc(l.start)}<small>${esc(l.end)}</small></div><div class="lesson-body"><strong>${esc(subject(l.subject)?.name||'Hodina')}</strong><small>${l.cancelled?'Odpadá':l.change?'Změna · '+esc(l.note||l.room||l.teacher||'Suplování'):esc(l.room||'Uložená výuka')}</small></div><button class="icon-button" data-action="lesson-detail" data-id="${esc(l.id)}" data-date="${date}" aria-label="Detail hodiny">${icon('chevron')}</button></div>`).join(''):empty('Pro tento den není uložená výuka.','Chybějící rozvrh neznamená volno. Aktuální hodiny najdeš v EduPage.','','','calendar')}</section><section class="panel substitutions-panel"><div class="panel-heading"><h2>Suplování a změny</h2><span class="change-count">${published.length+changes.length}</span></div>${published.map(c=>`<div class="change-item published"><span>${shortDate(c.date)} · ${esc(c.period)}. hodina · ${esc(c.className)}</span><strong>${esc(c.title)}</strong><small>Zveřejněné suplování třídy · EduPage</small></div>`).join('')}${changes.length?changes.map(c=>`<div class="change-item"><span>${shortDate(c.date)} · ${esc(c.start)}</span><strong>${c.action==='cancelled'?'Odpadá':c.action==='added'?'Přidaná hodina':'Suplování / změna'}</strong><p>${esc(subject(c.subject)?.name||c.note||'Detail v rozvrhu')}</p><small>${esc(c.source||'Vlastní záznam')} · ${formatChecked(c.checkedAt)}</small></div>`).join(''):published.length?'':'<div class="source-pending">'+icon('info')+'<strong>Suplování není ověřené</strong><p>Aktuální změny je potřeba načíst z přihlášeného EduPage. Prázdný seznam nepotvrzuje, že žádné nejsou.</p></div>'}<button class="secondary-button" data-action="school-substitutions">Otevřít suplování ↗</button></section></div>`;
}
function shortDate(date){return new Date(date+'T12:00:00').toLocaleDateString('cs-CZ',{day:'numeric',month:'numeric'});}
function lessonDetail(id,date){const l=scheduleForDate(state.lessons,date,state.substitutions,state.events).find(l=>l.id===id);if(!l)return;showModal(modalHeader(subject(l.subject)?.name||'Hodina')+`<div class="lesson-detail-time">${shortDate(date)} · ${esc(l.start)}–${esc(l.end)}</div><p class="modal-description">${l.cancelled?'Hodina odpadá.':esc(l.room||'Učebna neuvedena')}${l.teacher?' · '+esc(l.teacher):''}</p>${l.change?`<p class="change-note">${esc(l.note||'Změna rozvrhu')}${l.originalSubject?' · Původně '+esc(subject(l.originalSubject)?.name):''}</p><p class="storage-note">${esc(l.source||'Vlastní záznam')} · ${formatChecked(l.checkedAt)}</p><button class="danger-button" data-action="change-delete" data-id="${esc(l.displayRootId||l.id)}">Odebrat změnu</button>`:`<button class="secondary-button" data-action="lesson-edit" data-id="${esc(state.lessons.some(x=>x.id===l.id)?l.id:l.displayRootId||l.id)}">${icon('edit')} Upravit hodinu</button>`}`);}
function changeModal(){const date=addDays(scheduleWeek,weekDay-1);showModal(modalHeader('Změna rozvrhu')+`<p class="modal-description">Vlastní záznam podle informace ze školy. Přepisuje pouze tento konkrétní den.</p><form data-form="change"><div class="form-row"><div class="form-field"><label for="change-date">Datum</label><input class="input" id="change-date" type="date" name="date" value="${date}" required></div><div class="form-field"><label for="change-action">Změna</label><select id="change-action" name="action"><option value="changed">Suplování / změna</option><option value="cancelled">Odpadá</option><option value="added">Přidaná hodina</option></select></div></div><div class="form-row"><div class="form-field"><label for="change-start">Původní začátek</label><input class="input" id="change-start" type="time" name="start" value="08:30" required></div><div class="form-field"><label for="change-end">Konec</label><input class="input" id="change-end" type="time" name="end" value="09:15" required></div></div><div class="form-field"><label for="change-subject">Předmět</label><select id="change-subject" name="subject">${subjectOptions('',true)}</select><small>Při změně prázdná volba zachová původní předmět.</small></div><div class="form-field"><label for="change-room">Učebna</label><input class="input" id="change-room" name="room" maxlength="100"></div><div class="form-field"><label for="change-note">Poznámka / vyučující</label><input class="input" id="change-note" name="note" maxlength="1000"></div><div class="modal-actions"><button type="button" class="secondary-button" data-action="modal-close">Zrušit</button><button class="primary-button">Uložit změnu</button></div></form>`);}
function openSchool(kind){const path=kind==='grades'?'/znamky/':kind==='substitutions'?'/substitution/':'/dashboard/eb.php?mode=timetable';const url=new URL(path,state.profile.edupage).href;if(nativeMode)nativeSend('school',{url});else window.open(url,'_blank','noopener,noreferrer');}

function gradeUnit(g){return g.assessmentType==='points'?'body':g.assessmentType==='percent'?'procenta':g.assessmentType==='text'?'hodnocení':g.weight===null?'bez váhy':'× '+g.weight;}
function gradeDisplay(g){return g.display||String(g.value??'—').replace('.',',');}
function gradesView(){const grades=state.grades||[],groups=state.subjects.filter((s,i,all)=>all.findIndex(x=>x.name.replace(' a literatura','')===s.name.replace(' a literatura',''))===i),failure=state.eduSync?.errors?.some(e=>e==='grades'||e==='grades_partial');
 return heading('Známky','Hodnocení z EduPage · váhy a průměry',false)+`<div class="grades-toolbar"><div class="segmented"><span class="selected">Předměty</span><span>${grades.length} hodnocení</span></div><div><button class="secondary-button" data-action="school-grades">EduPage ↗</button><button class="primary-button" data-action="edupage-sync">Synchronizovat EduPage</button><button class="icon-button" data-action="grade-new" aria-label="Zapsat vlastní známku">${icon('plus')}</button></div></div>${failure?`<div class="connection-alert"><strong>${state.eduSync?.gradePartial?'Část hodnocení se nepodařilo přečíst':'Známky se naposledy nepodařilo načíst'}</strong><span>${state.eduSync?.gradePartial?'Ostatní hodnocení se zobrazují; dřívější data zůstala zachovaná.':'Spusť nové načtení. Pokud chyba přetrvá, v Nastavení můžeš změnit uložené přihlášení.'}</span><button data-action="edupage-sync">Zkusit znovu ↗</button></div>`:''}<div class="grade-grid">${groups.length?groups.map(s=>{const rows=grades.filter(g=>g.subject===s.id),schoolRows=rows.filter(g=>g.source==='EduPage'),summary=gradeSummary(rows),avg=summary?.value??null;return `<section class="panel grade-card" style="--subject-color:${s.color}"><div class="grade-card-head"><div><span class="subject-kicker">${esc(schoolRows.length?'EDUPAGE':'VLASTNÍ ZÁZNAMY')}</span><h2>${esc(s.name)}</h2></div><div class="grade-result"><span class="grade-average">${avg===null?'—':avg.toLocaleString('cs-CZ',{minimumFractionDigits:2,maximumFractionDigits:2})+(summary?.unit?' '+summary.unit:'')}</span>${summary?.unit==='%'&&avg!==null?`<span class="estimated-grade grade-${estimatedGrade(avg)}">Vychází <b>${estimatedGrade(avg)}</b></span>`:''}</div></div><div class="grade-dots">${rows.sort((a,b)=>b.date.localeCompare(a.date)).map(g=>`<button class="grade-dot ${g.value===null?'is-assessment':''}" data-action="grade-detail" data-id="${esc(g.id)}" title="${esc(g.title)} · ${shortDate(g.date)}">${esc(gradeDisplay(g))}<small>${esc(gradeUnit(g))}</small></button>`).join('')}</div><div class="grade-card-foot"><span>${rows.length} hodnocení · ${esc(summary?.label||(!rows.length?'Bez hodnocení':'Souhrn zatím nelze určit'))}</span><button data-action="subject-open" data-id="${esc(s.id)}">Zápisky ↗</button></div></section>`;}).join(''):empty('Známky zatím nejsou načtené.','Klikni na Synchronizovat EduPage. Heslo se zadává do zabezpečeného pole aplikace.','','','star')}</div><p class="storage-note">Souhrny se počítají z hodnocení načtených z EduPage: u známek podle vah, u bodů jako podíl získaných a možných bodů, u procent jako vážený průměr. Odhad známky používá tvoje hranice: 90 % = 1, 75 % = 2, 60 % = 3, 45 % = 4, méně = 5. Výslednou klasifikaci určuje učitel. Bez úplných údajů se zobrazí pomlčka.${state.eduSync?.gradeCheckedAt?' Poslední načtení: '+formatChecked(state.eduSync.gradeCheckedAt)+'.':''}</p>`;
}

function gradeModal(){if(!state.subjects.length)return toast('Nejdřív přidej předmět.');showModal(modalHeader('Zapsat známku')+`<p class="modal-description">Vlastní záznam v Orbitu. Nemění školní klasifikaci.</p><form data-form="grade"><div class="form-field"><label for="grade-subject">Předmět</label><select id="grade-subject" name="subject">${subjectOptions(state.subjects[0].id)}</select></div><div class="form-row"><div class="form-field"><label for="grade-value">Známka</label><input class="input" id="grade-value" name="value" type="number" min="1" max="5" step="0.01" value="1" required></div><div class="form-field"><label for="grade-weight">Váha</label><input class="input" id="grade-weight" name="weight" type="number" min="0.01" max="100" step="0.01" value="1" required></div></div><div class="form-field"><label for="grade-title">Popis</label><input class="input" id="grade-title" name="title" maxlength="200" placeholder="Např. test z rovnic"></div><div class="form-field"><label for="grade-date">Datum</label><input class="input" id="grade-date" name="date" type="date" value="${todayKey()}" required></div><div class="modal-actions"><button type="button" class="secondary-button" data-action="modal-close">Zrušit</button><button class="primary-button">Uložit známku</button></div></form>`);}
function gradeDetail(id){const g=(state.grades||[]).find(g=>g.id===id);if(!g)return;showModal(modalHeader(esc(g.title||subject(g.subject)?.name||'Známka'))+`<div class="lesson-detail-time">${esc(gradeDisplay(g))} <span class="muted">${esc(gradeUnit(g))}</span></div><p class="modal-description">${esc(subject(g.subject)?.name)} · ${shortDate(g.date)} · ${esc(g.source||'Orbit')}</p><div class="modal-actions"><button class="danger-button" data-action="grade-delete" data-id="${esc(id)}">Smazat známku</button><button class="secondary-button" data-action="modal-close">Zavřít</button></div>`);}

function subjectsView(){return heading('Předměty','Zápisky a přímé odkazy na skutečné kurzy v Classroom.',false)+`<div class="toolbar"><button class="primary-button" data-action="subject-new">${icon('plus')} Přidat předmět</button></div><div class="subject-grid">${state.subjects.map((s,i)=>`<button class="panel subject-card" data-action="subject-open" data-id="${esc(s.id)}" style="--subject-color:${s.color}"><div class="subject-icon">${['π','Aa','En','&lt;/&gt;','φ','Es'][i]||icon('book')}</div><h3>${esc(s.name)}</h3><p>${state.tasks.filter(t=>t.subject===s.id&&!t.done).length} úkolů · ${s.notes?'Zápisky uložené':'Prostor pro zápisky'}</p><span>↗</span></button>`).join('')}</div>`;}
function focusView(){return heading('Soustředění','Časovač a historie dokončených bloků.',false)+`<div class="all-focus">${focusCard()}<section class="panel focus-history">${panelHeading('Tvoje dokončené bloky')}<p class="storage-note">Blok se započítá až po doběhnutí časovače. Po uspání nebo zavření aplikace se vyhodnotí při návratu.</p>${state.sessions.length?state.sessions.slice(-7).reverse().map(s=>`<div class="history-row"><span>${new Date(s.date+'T12:00:00').toLocaleDateString('cs-CZ',{day:'numeric',month:'long'})}</span><span>${s.minutes} minut soustředění</span></div>`).join(''):empty('Zatím žádné dokončené bloky.','Spusť svůj první blok. Najdeš ho pak právě tady.','','','focus')}</section></div>`;}
function settingsView(){return heading('Nastavení','Účty, data a klávesové zkratky. Orbit 4.3',false)+`<div class="settings-grid"><section class="panel"><h2>Tvůj profil</h2><form data-form="profile"><div class="form-field"><label for="profile-name">Jméno</label><input class="input" id="profile-name" name="name" maxlength="100" value="${esc(state.profile.name)}" required></div><div class="form-field"><label for="profile-email">Školní Google účet</label><input class="input" id="profile-email" name="email" type="email" maxlength="150" value="${esc(state.profile.email)}" required><small>Použije se při otevření Classroom, Disku a Gmailu. Samotné uvedení adresy účet nepropojí.</small></div><div class="form-field"><label for="edupage-url">Adresa EduPage</label><input class="input" id="edupage-url" name="edupage" type="url" maxlength="500" value="${esc(state.profile.edupage)}" required><small>Přihlášení probíhá přímo v EduPage.</small></div><button class="primary-button" type="submit">Uložit nastavení</button></form></section><section class="panel"><h2>Školní služby</h2><p class="settings-description">Otevři školní služby se svým účtem. EduPage se připojuje zabezpečeným přihlášením; ostatní služby se otevírají přes přímé odkazy.</p>${[['Google Classroom','classroom'],['EduPage','edupage'],['Google Drive','drive'],['Školní Gmail','gmail']].map(([n,k])=>`<div class="status-line"><a target="_blank" rel="noopener noreferrer" href="${esc(schoolUrl(k))}">${n} ↗</a><span class="status">${['classroom','edupage'].includes(k)?'Uložený přehled · přihlášení zvlášť':'Odkaz'}</span></div>`).join('')}<p class="settings-description">Uložený přehled pochází z dřívějšího načtení školních služeb. ${extensionMode?'Rozšíření načítá rozpoznané termíny při otevření školních stránek v Chrome.':'V této verzi není ověřené průběžné načítání všech úkolů a celého rozvrhu. Přehled může být neúplný.'}</p><button class="secondary-button" data-action="sources">Stav školních zdrojů</button><button class="secondary-button" data-action="edupage-sync">Synchronizovat EduPage</button><button class="secondary-button" data-action="edupage-forget">Změnit přihlášení EduPage</button><p class="source-details">Informace o službě najdeš na <a href="https://www.edupage.org/" target="_blank" rel="noopener noreferrer">webu EduPage ↗</a>.</p></section><section class="panel"><h2>Tvoje data</h2><p class="settings-description">Úkoly, rozvrh a zápisky se ukládají na tomto zařízení, nezávisle na umístění aplikace. Mezi aplikacemi a zařízeními se automaticky nesynchronizují. Pro přenos slouží záloha.</p><button class="secondary-button" data-action="export">${icon('download')} Stáhnout zálohu</button><button class="secondary-button" data-action="import">${icon('upload')} Obnovit ze zálohy</button><input class="file-input" id="import-file" type="file" accept="application/json,.json"><p class="storage-note">Obnovení vyžaduje potvrzení před nahrazením současných dat.</p></section><section class="panel"><h2>Nástroje</h2><p class="settings-description">Prohlédni si dashboard s ukázkovými úkoly a rozvrhem. Tvoje vlastní data zůstanou uložená zvlášť.</p><button class="secondary-button" data-action="${isDemo?'demo-exit':'demo'}">${isDemo?'Zpět k vlastním datům':'Otevřít ukázkový režim'} ${icon('arrow')}</button><p class="settings-description">Orbit funguje samostatně na Macu i bez internetu. Školní odkazy připojení potřebují. Klávesové zkratky: ⌘ K hledání, N nový úkol, ⌘ , nastavení.</p></section></div>`;}
function showModal(html){delete modal.dataset.calendarDate;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();hydrateIcons();}
function calendarDayModal(date){const list=sortedTasks().filter(t=>t.due===date),events=(state.events||[]).filter(e=>e.date===date);showModal(modalHeader(new Date(date+'T12:00:00').toLocaleDateString('cs-CZ',{weekday:'long',day:'numeric',month:'long'}))+events.map(e=>`<div class="school-event">${esc(e.title)}</div>`).join('')+(list.length?list.map(taskRow).join(''):empty('Na tento den tu nemáš žádný úkol.','Můžeš si přidat vlastní termín.'))+`<div class="modal-actions"><button class="primary-button" data-action="task-new">${icon('plus')} Přidat úkol</button></div>`);modal.dataset.calendarDate=date;}

function modalHeader(title){return `<div class="modal-header"><h2>${title}</h2><button class="icon-button" data-action="modal-close" aria-label="Zavřít">${icon('close')}</button></div>`;}
function subjectOptions(selected='',personal=false){return (personal?'<option value="">Osobní / bez předmětu</option>':'')+state.subjects.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('');}
function taskModal(id){const t=state.tasks.find(t=>t.id===id)||{title:'',subject:'',kind:'task',due:selectedDate,notes:'',priority:false};showModal(modalHeader(id?'Detail úkolu':'Nový úkol')+`<p class="modal-description">${t.source?`${esc(t.source)} · načteno ${formatChecked(t.checkedAt)}. Změny a dokončení platí pouze v Orbitu.`:'Úkol nebo test uložený v Orbitu.'}</p>${t.sourceUrl?`<a class="secondary-button" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(t.sourceUrl))}">Otevřít původní zadání ↗</a>`:''}<form data-form="task" data-id="${esc(id||'')}"><div class="form-field"><label for="task-title">Co potřebuješ udělat?</label><input autofocus class="input" id="task-title" name="title" placeholder="Třeba dokončit projekt z informatiky" maxlength="200" value="${esc(t.title)}" required></div><div class="form-row"><div class="form-field"><label for="task-subject">Předmět</label><select id="task-subject" name="subject">${subjectOptions(t.subject,true)}</select></div><div class="form-field"><label for="task-kind">Typ</label><select id="task-kind" name="kind">${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${k===t.kind?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="form-field"><label for="task-due">Termín</label><input class="input" id="task-due" name="due" type="date" value="${t.due}" required></div><div class="form-field"><label for="task-notes">Poznámka</label><textarea id="task-notes" name="notes" maxlength="5000" placeholder="Co konkrétně udělat, na co nezapomenout…">${esc(t.notes)}</textarea></div><label class="checkbox-field"><input type="checkbox" name="priority" ${t.priority?'checked':''}>Tohle je moje priorita</label><div class="modal-actions">${id?`<button type="button" class="danger-button" data-action="task-delete" data-id="${esc(id)}">Smazat</button>`:''}<button type="button" class="secondary-button" data-action="modal-close">Zrušit</button><button type="submit" class="primary-button">${id?'Uložit změny':'Přidat úkol'}</button></div></form>`);}
function lessonModal(id){if(!state.subjects.length){toast('Nejdřív přidej alespoň jeden předmět.');return;}const l=state.lessons.find(l=>l.id===id)||{subject:state.subjects[0].id,day:weekDay,start:'08:30',end:'09:15',room:''};showModal(modalHeader(id?'Upravit hodinu':'Přidat do rozvrhu')+`<form data-form="lesson" data-id="${esc(id||'')}"><div class="form-field"><label for="lesson-subject">Předmět</label><select id="lesson-subject" name="subject">${subjectOptions(l.subject)}</select></div><div class="form-field"><label for="lesson-date">Konkrétní datum (prázdné = každý týden)</label><input class="input" id="lesson-date" name="date" type="date" value="${esc(l.date||'')}"></div><div class="form-field"><label for="lesson-day">Den týdne</label><select id="lesson-day" name="day">${weekdays.slice(1).map((d,i)=>`<option value="${i+1}" ${l.day===i+1?'selected':''}>${d}</option>`).join('')}</select></div><div class="form-row"><div class="form-field"><label for="lesson-start">Začátek</label><input class="input" name="start" id="lesson-start" type="time" value="${esc(l.start)}" required></div><div class="form-field"><label for="lesson-end">Konec</label><input class="input" name="end" id="lesson-end" type="time" value="${esc(l.end)}" required></div></div><div class="form-field"><label for="lesson-room">Učebna</label><input class="input" id="lesson-room" name="room" maxlength="100" placeholder="Například 2.01" value="${esc(l.room)}"></div><div class="modal-actions">${id?`<button type="button" class="danger-button" data-action="lesson-delete" data-id="${esc(id)}">Smazat</button>`:''}<button type="button" class="secondary-button" data-action="modal-close">Zrušit</button><button class="primary-button" type="submit">Uložit hodinu</button></div></form>`);}
function subjectModal(id){const s=subject(id);if(!s)return;showModal(modalHeader(esc(s.name))+`<div class="panel-heading" style="margin-top:20px"><span class="note-save-state" id="notes-state">Zápisky se ukládají automaticky</span><button class="small-link" data-action="subject-edit" data-id="${esc(id)}">Upravit předmět ${icon('edit')}</button></div><div class="form-field"><label for="subject-notes">Tvoje zápisky</label><textarea class="note-editor" id="subject-notes" data-subject="${esc(id)}" maxlength="100000" placeholder="Co si chceš z hodiny zapamatovat?">${esc(s.notes)}</textarea></div><h3 style="font-size:12px">Materiály a odkazy</h3><div class="subject-link-list">${s.links.map((l,i)=>`<div><a href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener noreferrer">${esc(l.title)} ↗</a><button data-action="link-delete" data-id="${esc(id)}" data-index="${i}" aria-label="Odebrat odkaz ${esc(l.title)}">×</button></div>`).join('')}</div><form data-form="subject-link" data-id="${esc(id)}"><div class="form-row"><div class="form-field"><label for="link-title">Název materiálu</label><input class="input" name="title" id="link-title" maxlength="100" placeholder="Zápisky v Notion" required></div><div class="form-field"><label for="link-url">Odkaz</label><input class="input" name="url" id="link-url" type="url" maxlength="2000" placeholder="https://…" required></div></div><button class="secondary-button" type="submit">${icon('plus')} Přidat odkaz</button></form>`);}
function subjectEditModal(id){const s=subject(id)||{name:'',color:COLORS[state.subjects.length%COLORS.length]};showModal(modalHeader(id?'Upravit předmět':'Nový předmět')+`<form data-form="subject" data-id="${esc(id||'')}"><div class="form-field"><label for="subject-name">Název</label><input class="input" name="name" id="subject-name" value="${esc(s.name)}" maxlength="100" required></div><div class="form-field"><label for="subject-color">Barva</label><input class="input" style="height:44px" id="subject-color" name="color" type="color" value="${s.color}"></div>${id?'<p class="storage-note">Smazáním předmětu se odstraní jeho zápisky a hodiny. Úkoly zůstanou mezi osobními.</p>':''}<div class="modal-actions">${id?`<button type="button" class="danger-button" data-action="subject-delete" data-id="${esc(id)}">Smazat předmět</button>`:''}<button type="button" class="secondary-button" data-action="modal-close">Zrušit</button><button class="primary-button" type="submit">Uložit předmět</button></div></form>`);}
function openSearch(){showModal(modalHeader('Hledat v Orbitu')+'<input class="input search-input" id="global-search" type="search" placeholder="Úkol, předmět, zápisek…" aria-label="Hledat"><div id="search-results"></div>');renderSearch('');setTimeout(()=>$('#global-search')?.focus(),50);}
function renderSearch(q){const match=x=>x.toLocaleLowerCase('cs').includes(q.toLocaleLowerCase('cs'));let ts=state.tasks.filter(t=>match(t.title)).slice(0,5),ss=state.subjects.filter(s=>match(s.name)||match(s.notes)).slice(0,5);$('#search-results').innerHTML=ts.map(t=>`<button class="search-result" data-action="task-edit" data-id="${esc(t.id)}">${icon('tasks')}<div><span>${esc(t.title)}</span><small>${esc(subject(t.subject)?.name||'Osobní')} · ${dueLabel(t.due)}</small></div></button>`).join('')+ss.map(s=>`<button class="search-result" data-action="subject-open" data-id="${esc(s.id)}">${icon('book')}<div><span>${esc(s.name)}</span><small>Předmět · zápisky a materiály</small></div></button>`).join('')||'<p class="no-results">Nic takového tu zatím není.</p>';}
function updateTimer(){if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.endsAt-Date.now())/1000));if(timer.remaining===0){timer.running=false;state.sessions.push({date:todayKey(),minutes:timer.minutes});state.sessions=state.sessions.slice(-2000);persist();toast(`Hotovo. ${timer.minutes} minut soustředění máš za sebou.`);render();return;}}const time=`${Math.floor(timer.remaining/60).toString().padStart(2,'0')}:${(timer.remaining%60).toString().padStart(2,'0')}`;document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=time);document.querySelectorAll('[data-timer-button]').forEach(e=>e.innerHTML=icon(timer.running?'pause':'play')+(timer.running?' Pozastavit':timer.remaining===0?' Znovu':timer.remaining<timer.minutes*60?' Pokračovat':' Začít'));document.querySelectorAll('[data-timer-label]').forEach(e=>e.textContent=timer.running?'Časovač běží':timer.remaining===0?'Blok dokončen':'Soustředěný blok');document.querySelectorAll('[data-timer-progress]').forEach(e=>e.style.width=`${100*(1-timer.remaining/(timer.minutes*60))}%`);document.title=timer.running?`${time} · Orbit`:'Orbit · Můj školní prostor';}
let pendingImport=null;
function afterMutation(message){persist();if(modal.open)modal.close();render();if(message)toast(message);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;
 if(action==='edupage-forget'){if(nativeMode)nativeSend('forget-edupage');else toast('Přihlášení spravuje aplikace Orbit pro Mac.');}
 else if(action==='edupage-sync'){if(isDemo)return toast('Nejdřív ukonči ukázkový režim.');if(syncBusy)return;if(nativeMode){nativeSend('sync',{start:scheduleWeek});toast('Připojuji EduPage…');}else toast('Přímá synchronizace je dostupná v aplikaci Orbit pro Mac.');}
 else if(action==='overview-day'){weekDay=Number(b.dataset.day);view='schedule';render();window.scrollTo({top:0,behavior:'smooth'});}
 else if(action==='week-prev'||action==='week-next'){scheduleWeek=addDays(scheduleWeek,action==='week-prev'?-7:7);render();}
 else if(action==='week-today'){scheduleWeek=mondayOf(todayKey());if(new Date(todayKey()+'T12:00:00Z').getUTCDay()===0)scheduleWeek=addDays(scheduleWeek,7);weekDay=weekday();render();}
 else if(action==='school-grades')openSchool('grades');else if(action==='grade-new')gradeModal();else if(action==='grade-detail')gradeDetail(id);else if(action==='grade-delete'){state.grades=(state.grades||[]).filter(g=>g.id!==id);afterMutation('Známka odebrána.');}
 else if(action==='school-timetable')openSchool('timetable');else if(action==='school-substitutions')openSchool('substitutions');
 else if(action==='lesson-detail')lessonDetail(id,b.dataset.date);else if(action==='change-new')changeModal();else if(action==='change-delete'){state.substitutions=(state.substitutions||[]).filter(x=>x.id!==id);afterMutation('Změna odebrána.');}
 else if(action==='navigate'){view=b.dataset.view;query='';subjectFilter='';kindFilter='';render();window.scrollTo({top:0});}
 else if(action==='task-new')taskModal();else if(action==='task-edit')taskModal(id);
 else if(action==='task-toggle'){const t=state.tasks.find(t=>t.id===id);if(t){t.done=!t.done;persist();render();if(modal.open&&modal.dataset.calendarDate)calendarDayModal(modal.dataset.calendarDate);}}
 else if(action==='task-star'){const t=state.tasks.find(t=>t.id===id);if(t){if(!t.priority&&state.tasks.filter(t=>t.priority&&!t.done).length>=3){toast('Můžeš označit nejvýš tři priority.');return;}t.priority=!t.priority;persist();render();}}
 else if(action==='task-delete'){const deleted=state.tasks.find(t=>t.id===id);showModal(modalHeader('Smazat úkol?')+`<p class="modal-description">${esc(deleted?.title)}</p><div class="modal-actions"><button class="secondary-button" data-action="task-edit" data-id="${esc(id)}">Zpět</button><button class="danger-button" data-action="task-delete-confirm" data-id="${esc(id)}">Smazat úkol</button></div>`);}
 else if(action==='task-delete-confirm'){state.tasks=state.tasks.filter(t=>t.id!==id);afterMutation('Úkol smazán.');}
 else if(action==='home-filter'){filter=b.dataset.filter;render();}
 else if(action==='all-tasks'){view='tasks';filter='open';render();}
 else if(action==='priority-view'){view='tasks';filter=state.tasks.some(t=>t.priority&&!t.done)?'priority':'open';render();}
 else if(action==='all-schedule'){view='schedule';render();}
 else if(action==='month-prev'||action==='month-next'){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+(action==='month-next'?1:-1),1);render();}
 else if(action==='calendar-date'){selectedDate=b.dataset.date;calendarDayModal(selectedDate);render();}
 else if(action==='lesson-new')lessonModal();else if(action==='lesson-edit')lessonModal(id);
 else if(action==='lesson-delete'){state.lessons=state.lessons.filter(l=>l.id!==id);afterMutation('Hodina odebrána.');}
 else if(action==='weekday'){weekDay=Number(b.dataset.day);render();}
 else if(action==='subject-open')subjectModal(id);else if(action==='subject-new')subjectEditModal();else if(action==='subject-edit')subjectEditModal(id);
 else if(action==='subject-delete'){showModal(modalHeader('Smazat předmět?')+`<p class="modal-description">Odstraní se zápisky, odkazy a hodiny předmětu ${esc(subject(id)?.name)}. Úkoly zůstanou jako osobní.</p><div class="modal-actions"><button class="secondary-button" data-action="subject-edit" data-id="${esc(id)}">Zpět</button><button class="danger-button" data-action="subject-delete-confirm" data-id="${esc(id)}">Smazat předmět</button></div>`);}
 else if(action==='subject-delete-confirm'){state.subjects=state.subjects.filter(s=>s.id!==id);state.lessons=state.lessons.filter(l=>l.subject!==id);state.substitutions=(state.substitutions||[]).filter(l=>l.subject!==id);state.grades=(state.grades||[]).filter(g=>g.subject!==id);state.tasks.forEach(t=>{if(t.subject===id)t.subject='';});afterMutation('Předmět smazán.');}
 else if(action==='link-delete'){subject(id)?.links.splice(Number(b.dataset.index),1);persist();subjectModal(id);}
 else if(action==='modal-close')modal.close();else if(action==='search')openSearch();
 else if(action==='sources')sourcesModal();
 else if(action==='quick-filter'){filter=b.dataset.filter;view='tasks';query='';render();}
 else if(action==='tests'){view='tasks';filter='open';query='';kindFilter='test';render();}
 else if(action==='calendar-export'){const text=calendarText(state.tasks,state.subjects);if(nativeMode){nativeSend('export',{name:'Orbit-terminy.ics',text});return;}const url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Orbit-terminy.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Termíny jsou připravené k importu do kalendáře.');}
 else if(action==='focus'){view='focus';render();}
 else if(action==='timer-toggle'){if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.endsAt-Date.now())/1000));timer.running=false;}else{if(timer.remaining===0)timer.remaining=timer.minutes*60;timer.endsAt=Date.now()+timer.remaining*1000;timer.running=true;}persist();updateTimer();}
 else if(action==='timer-reset'){timer.remaining=timer.minutes*60;timer.running=false;persist();updateTimer();}
 else if(action==='timer-preset'){if(timer.running){toast('Nejdřív časovač pozastav.');return;}timer.minutes=Number(b.dataset.minutes);timer.remaining=timer.minutes*60;persist();render();}
 else if(action==='demo'){if(isDemo)return;ownState=state;ownTimer={...timer};state=demoState();isDemo=true;timer={minutes:25,remaining:1500,running:false,endsAt:0};view='home';filter='open';render();toast('Ukázková data. Tvoje vlastní data jsou beze změny.');}
 else if(action==='demo-exit'){state=ownState;isDemo=false;timer={...ownTimer};filter='open';view='home';render();}
 else if(action==='export'){if(nativeMode){nativeSend('export',{name:`orbit-zaloha-${todayKey()}.json`,text:JSON.stringify(isDemo?ownState:state,null,2)});return;}const blob=new Blob([JSON.stringify(isDemo?ownState:state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`orbit-zaloha-${todayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Záloha vlastních dat je připravená ke stažení.');}
 else if(action==='import'){if(isDemo){toast('Nejdřív se vrať k vlastním datům.');return;}if(nativeMode)nativeSend('import');else $('#import-file').click();}
 else if(action==='import-confirm'&&pendingImport){state=pendingImport;ownState=state;timer=state.focusTimer?{...state.focusTimer}:{minutes:25,remaining:1500,running:false,endsAt:0};storageReadError=false;pendingImport=null;afterMutation('Záloha obnovena.');}
});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const f=new FormData(form),data=Object.fromEntries(f),id=form.dataset.id,type=form.dataset.form;
 if(type==='task'){if(!data.title.trim()||!validDate(data.due))return;const old=state.tasks.find(t=>t.id===id),t={...old,id:id||uid(),title:data.title.trim(),subject:data.subject,kind:data.kind,due:data.due,notes:data.notes,priority:f.has('priority'),done:old?.done||false};if(t.priority&&!old?.priority&&state.tasks.filter(t=>t.priority&&!t.done).length>=3){toast('Nech si nejvýš tři priority.');return;}if(old)Object.assign(old,t);else state.tasks.push(t);afterMutation('Úkol uložen.');}
 else if(type==='lesson'){if(data.end<=data.start){toast('Konec hodiny musí být později než začátek.');return;}const oldLesson=state.lessons.find(x=>x.id===id);const l={...oldLesson,id:id||uid(),subject:data.subject,day:Number(data.day),start:data.start,end:data.end,room:data.room.trim()};if(data.date){if(!validDate(data.date)||[0,6].includes(new Date(data.date+'T12:00:00Z').getUTCDay())){toast('Vyber platný školní den.');return;}l.date=data.date;l.day=new Date(data.date+'T12:00:00Z').getUTCDay();}else delete l.date;const overlap=state.lessons.some(x=>lessonsOverlap(x,l));if(overlap){toast('V tomto čase už máš jinou hodinu.');return;}const old=state.lessons.find(l=>l.id===id);if(old){if(!l.date)delete old.date;Object.assign(old,l);}else state.lessons.push(l);weekDay=l.day;if(l.date)scheduleWeek=mondayOf(l.date);afterMutation('Hodina uložena.');}
 else if(type==='grade'){const value=Number(data.value),weight=Number(data.weight);if(!Number.isFinite(value)||value<1||value>5||!Number.isFinite(weight)||weight<=0||weight>100||!validDate(data.date)){toast('Zkontroluj známku, váhu a datum.');return;}state.grades=state.grades||[];if(state.grades.length>=3000)return toast('Byl dosažen limit známek.');state.grades.push({...data,id:uid(),value,weight,source:'Orbit'});afterMutation('Známka uložena.');}
 else if(type==='change'){if(!validDate(data.date)||data.end<=data.start){toast('Zkontroluj datum a čas hodiny.');return;}const rows=scheduleForDate(state.lessons,data.date,[],state.events),old=rows.find(l=>l.start===data.start);if(data.action!=='added'&&!old){toast('V tomto čase nemáš uloženou původní hodinu.');return;}if(data.action==='added'&&!data.subject){toast('Přidaná hodina potřebuje předmět.');return;}state.substitutions=state.substitutions||[];state.substitutions=state.substitutions.filter(x=>!(x.date===data.date&&x.start===data.start));state.substitutions.push({...data,id:uid(),source:'Vlastní záznam',checkedAt:new Date().toISOString()});scheduleWeek=mondayOf(data.date);weekDay=new Date(data.date+'T12:00:00Z').getUTCDay()||1;afterMutation('Změna rozvrhu uložena.');}
 else if(type==='subject'){if(!data.name.trim())return;const old=subject(id);if(old){old.name=data.name.trim();old.color=data.color;}else state.subjects.push({id:uid(),name:data.name.trim(),color:data.color,notes:'',links:[]});afterMutation('Předmět uložen.');}
 else if(type==='subject-link'){const s=subject(id),url=safeUrl(data.url);if(!url){toast('Použij platný odkaz začínající https:// nebo http://.');return;}if(!data.title.trim())return;if(s.links.length>=50){toast('U předmětu může být nejvýš 50 odkazů.');return;}s.links.push({title:data.title.trim(),url});persist();subjectModal(id);toast('Odkaz přidán.');}
 else if(type==='profile'){if(!data.name.trim()||!safeUrl(data.edupage))return;state.profile={name:data.name.trim(),email:data.email.trim(),edupage:safeUrl(data.edupage)};persist();render();toast('Nastavení uloženo.');}
});
document.addEventListener('input',e=>{if(e.target.id==='quick-note'){state.quickNote=e.target.value;persist();$('#quick-note-status').textContent=storageAvailable?'Uloženo':'Neuloženo';}else if(e.target.id==='subject-notes'){const s=subject(e.target.dataset.subject);if(s){s.notes=e.target.value;persist();$('#notes-state').textContent=storageAvailable?'Uloženo v Orbitu':'Uložení není dostupné';}}else if(e.target.id==='global-search')renderSearch(e.target.value);else if(e.target.id==='task-search'){query=e.target.value;const focused=e.target,position=focused.selectionStart;const holder=document.createElement('div');holder.innerHTML=tasksView();$('#task-list').innerHTML=holder.querySelector('#task-list').innerHTML;}});
document.addEventListener('change',async e=>{if(e.target.id==='kind-filter'){kindFilter=e.target.value;render();}else if(e.target.id==='task-filter'){filter=e.target.value;render();}else if(e.target.id==='subject-filter'){subjectFilter=e.target.value;render();}else if(e.target.id==='import-file'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Záloha je příliš velká. Limit je 2 MB.');pendingImport=validateState(JSON.parse(await file.text()));showModal(modalHeader('Obnovit data ze zálohy?')+`<p class="modal-description">Tato záloha obsahuje ${pendingImport.tasks.length} úkolů, ${pendingImport.subjects.length} předmětů a ${pendingImport.lessons.length} hodin. Nahrazení odstraní současná data v tomto prohlížeči. Před pokračováním si můžeš stáhnout současnou zálohu.</p><div class="modal-actions"><button class="secondary-button" data-action="export">Stáhnout současná data</button><button class="primary-button" data-action="import-confirm">Nahradit a obnovit</button></div>`);}catch(error){toast(error.message||'Zálohu se nepodařilo načíst.');}e.target.value='';}});
document.addEventListener('keydown',e=>{const editing=e.target.matches('input,textarea,select,[contenteditable]');if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}else if((e.metaKey||e.ctrlKey)&&e.key===','){e.preventDefault();if(modal.open)modal.close();view='settings';render();}else if(!editing&&!modal.open&&!e.metaKey&&!e.ctrlKey&&e.key.toLowerCase()==='n'){e.preventDefault();taskModal();}});
modal.addEventListener('click',e=>{if(e.target!==modal)return;const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimer();});
setInterval(()=>{updateTimer();updateLessonClock();refreshDate();},500);hydrateIcons();persist();render();
if(!storageAvailable)toast('Uložená data se nepodařilo přečíst. Původní data nebyla přepsána; obnov zálohu v Nastavení.');

async function startSchoolBridge(){
 if(!globalThis.chrome?.runtime?.id||!chrome.storage?.local)return;
 extensionMode=true;
 const normalized=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
 async function receive(sources){if(!sources||typeof sources!=='object')return;let changed=false;state.liveSources=state.liveSources||{};
  for(const source of ['Classroom','EduPage']){const data=sources[source];if(!data||!Array.isArray(data.tasks)||data.tasks.length>1000||isNaN(Date.parse(data.checkedAt)))continue;state.liveSources[source]={checkedAt:data.checkedAt,status:data.status};state.schoolCheckedAt=[state.schoolCheckedAt||'',data.checkedAt].sort().at(-1);
   for(const raw of data.tasks){const t={...raw,title:typeof raw?.title==='string'?raw.title.replace(/\s+ČJL\s*1\.?\s*MP3(?:\s+(?:Today|Tomorrow|Dnes|Zítra).*)?$/i,''):raw?.title};if(!t||typeof t.title!=='string'||t.title.length>200||!validDate(t.due)||!safeUrl(t.sourceUrl)||typeof t.subjectName!=='string'||t.subjectName.length>100||!['task','test','project'].includes(t.kind))continue;
    let subj=state.subjects.find(s=>normalized(s.name)===normalized(t.subjectName));
    const existing=state.tasks.find(x=>x.source===source&&((x.remoteId&&x.remoteId===t.remoteId)||(source==='Classroom'&&x.sourceUrl===t.sourceUrl)));
    if(!subj&&existing)subj=subject(existing.subject);
    if(!subj){if(state.subjects.length>=100)continue;subj={id:uid(),name:t.subjectName,color:COLORS[state.subjects.length%COLORS.length],notes:'',links:[]};state.subjects.push(subj);}
    if(existing){if(existing.due!==t.due||existing.title!==t.title)changed=true;Object.assign(existing,{title:t.title,due:t.due,dueTime:t.dueTime||'',sourceUrl:safeUrl(t.sourceUrl),checkedAt:t.checkedAt||data.checkedAt,remoteId:t.remoteId,statusUnverified:!!t.statusUnverified});}
    else if(state.tasks.length<2000){state.tasks.push({id:uid(),title:t.title,subject:subj.id,due:t.due,dueTime:t.dueTime||'',kind:t.kind,source,sourceUrl:safeUrl(t.sourceUrl),remoteId:String(t.remoteId||'').slice(0,500),checkedAt:t.checkedAt||data.checkedAt,notes:String(t.notes||'').slice(0,5000),statusUnverified:!!t.statusUnverified,done:false,priority:false});changed=true;}
   }
  }
  persist();if(!modal.open&&!document.activeElement?.matches('textarea,input'))render();if(changed)toast('Školní termíny aktualizovány z otevřené stránky.');
 }
 const data=await chrome.storage.local.get('orbitSchoolSources');await receive(data.orbitSchoolSources);
 chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&changes.orbitSchoolSources)receive(changes.orbitSchoolSources.newValue);});render();
}
startSchoolBridge().catch(()=>toast('Načítání školních zdrojů není dostupné.'));

function notionPages(){return [];}
function attachNotionPages(){for(const page of notionPages()){const target=state.subjects.find(x=>x.name===page.subject);if(target&&!target.links.some(l=>l.url===page.url))target.links.push({title:'Notion · '+page.title,url:page.url});}}
function notionView(){return heading('Zápisky v Notionu','Ve veřejné šabloně nejsou osobní odkazy. Přidej je u svých předmětů.',false)+`<div class="subject-grid">${notionPages().map(p=>`<a class="panel subject-card" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" style="--subject-color:#b6a1ff"><div class="subject-icon">N</div><h3>${esc(p.title)}</h3><p>${esc(p.subject)} · Otevřít v Notionu ↗</p></a>`).join('')}</div><p class="storage-note">Odkazy jsou také u jednotlivých předmětů. Orbit nekopíruje ani neupravuje obsah zápisků.</p>`;}
function updateLessonClock(){const el=$('#lesson-live');if(!el)return;const status=lessonStatus(state.lessons,new Date(),state.substitutions,state.events),remaining=status.remaining,clock=`${Math.floor(remaining/3600)?Math.floor(remaining/3600)+':':''}${String(Math.floor(remaining/60)%60).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;
 const name=subject(status.lesson?.subject)?.name||'',label=status.phase==='lesson'?'Do přestávky':status.phase==='break'?'Do další hodiny':status.phase==='before'?'Do začátku výuky':status.phase==='finished'?'Dnešní výuka skončila':[0,6].includes(new Date(todayKey()+'T12:00:00Z').getUTCDay())?'Dnes je víkend':'Pro dnešek není ověřený rozvrh',signature=JSON.stringify([status.phase,status.lesson?.id,name,status.lesson?.start,status.lesson?.end]);
 if(el.dataset.signature!==signature){el.dataset.signature=signature;el.className='lesson-live panel phase-'+status.phase;el.innerHTML=`<div class="lesson-live-info">${icon('clock')}<div><strong>${esc(label)}</strong><span>${status.lesson?esc(name)+' · '+esc(status.lesson.start)+'–'+esc(status.lesson.end):'Odpočet vychází z uložených hodin a jejich změn.'}</span></div></div>${status.lesson?'<strong class="lesson-live-clock"></strong>':''}<button class="small-link" data-action="all-schedule">Rozvrh ${icon('arrow')}</button>`;}const clockEl=el.querySelector('.lesson-live-clock');if(clockEl)clockEl.textContent=clock;
}
globalThis.orbitStorageResult=ok=>{storageAvailable=!!ok;updateSaveStatus();if(!ok)toast('Uložení na Mac selhalo. Stáhni zálohu.');};
globalThis.orbitImport=text=>{try{pendingImport=validateState(JSON.parse(text));showModal(modalHeader('Obnovit zálohu?')+`<p class="modal-description">${pendingImport.tasks.length} úkolů · ${pendingImport.lessons.length} hodin. Současná data budou nahrazena.</p><div class="modal-actions"><button class="secondary-button" data-action="export">Uložit současnou zálohu</button><button class="primary-button" data-action="import-confirm">Obnovit</button></div>`);}catch(e){toast(e.message||'Neplatná záloha.');}};
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(nativeMode&&a&&/^https?:/.test(a.href)){e.preventDefault();nativeSend(a.href.startsWith('https://school.edupage.org/')?'school':'external',{url:a.href});}});

globalThis.orbitEdupageReceive=payload=>{try{if(isDemo)return;state=mergeEdupageData(state,payload);ownState=state;persist();render();toast(payload.errors?.length?'EduPage načteno částečně; neúspěšné části zachovány.':'Data EduPage byla přenesena do dashboardu.');}catch(e){toast(e.message||'Import EduPage selhal.');}};
globalThis.orbitSyncError=message=>{syncErrorText=String(message);syncBusy=false;updateSyncStatus();toast(message);};

function updateSyncStatus(){document.querySelectorAll('[data-action="edupage-sync"]').forEach(b=>{b.disabled=syncBusy;b.textContent=syncBusy?'Synchronizuji…':'Synchronizovat EduPage';});const status=$('#sync-status');if(status){status.hidden=!syncBusy&&!syncErrorText;status.textContent=syncBusy?'Načítám EduPage. První instalace konektoru může trvat několik minut. Aplikaci můžeš dál používat.':syncErrorText;}}
globalThis.orbitSyncStatus=busy=>{syncBusy=!!busy;if(syncBusy)syncErrorText='';updateSyncStatus();};
function refreshDate(){const now=todayKey();if(now===lastRenderedDate||modal.open||document.activeElement?.matches('input,textarea,select,[contenteditable]'))return;if(selectedDate===lastRenderedDate){selectedDate=now;calendarDate=new Date(now+'T12:00:00');}render();}
